begin;
create or replace function private.has_org_access(target_org uuid) returns boolean language sql stable security definer set search_path = pg_catalog, iam as $$ select exists(select 1 from iam.organization_memberships m where m.organization_id=target_org and m.user_id=auth.uid() and m.status='active'); $$;
create or replace function private.has_company_access(target_org uuid, target_company uuid) returns boolean language sql stable security definer set search_path = pg_catalog, iam as $$ select exists(select 1 from iam.company_memberships cm join iam.organization_memberships om on om.id=cm.organization_membership_id where om.organization_id=target_org and om.user_id=auth.uid() and om.status='active' and cm.company_id=target_company and cm.status='active'); $$;
create or replace function private.has_permission(target_org uuid, target_company uuid, wanted text) returns boolean language sql stable security definer set search_path = pg_catalog, iam as $$ select exists(select 1 from iam.organization_memberships om join iam.member_app_roles mar on mar.organization_membership_id=om.id join iam.role_permissions rp on rp.role_id=mar.role_id join iam.permissions p on p.id=rp.permission_id where om.organization_id=target_org and om.user_id=auth.uid() and om.status='active' and (mar.company_id is null or mar.company_id=target_company) and mar.valid_from<=now() and (mar.valid_until is null or mar.valid_until>now()) and p.permission_key=wanted); $$;
revoke all on function private.has_org_access(uuid) from public;
revoke all on function private.has_company_access(uuid,uuid) from public;
revoke all on function private.has_permission(uuid,uuid,text) from public;
grant execute on function private.has_org_access(uuid) to authenticated;
grant execute on function private.has_company_access(uuid,uuid) to authenticated;
grant execute on function private.has_permission(uuid,uuid,text) to authenticated;
alter table platform.organizations enable row level security; alter table platform.companies enable row level security; alter table iam.profiles enable row level security; alter table iam.organization_memberships enable row level security; alter table iam.company_memberships enable row level security; alter table billing.application_subscriptions enable row level security; alter table audit.events enable row level security; alter table audit.ui_events enable row level security; alter table real_estate.properties enable row level security; alter table real_estate.units enable row level security; alter table integrations.mpesa_accounts enable row level security; alter table integrations.mpesa_callbacks enable row level security; alter table communications.conversations enable row level security; alter table communications.messages enable row level security;
create policy organizations_select_member on platform.organizations for select to authenticated using (private.has_org_access(id));
create policy companies_select_member on platform.companies for select to authenticated using (private.has_company_access(organization_id,id));
create policy profiles_select_self on iam.profiles for select to authenticated using (user_id=auth.uid());
create policy memberships_select_self on iam.organization_memberships for select to authenticated using (user_id=auth.uid());
create policy company_memberships_select_self on iam.company_memberships for select to authenticated using (exists(select 1 from iam.organization_memberships om where om.id=organization_membership_id and om.user_id=auth.uid()));
create policy subscriptions_select_member on billing.application_subscriptions for select to authenticated using (private.has_org_access(organization_id));
create policy audit_select_authorized on audit.events for select to authenticated using (private.has_permission(organization_id,company_id,'admin.audit.read') or private.has_permission(organization_id,company_id,'platform.audit.read'));
create policy audit_insert_authenticated on audit.events for insert to authenticated with check (actor_user_id=auth.uid() and private.has_org_access(organization_id));
create policy ui_event_insert_self on audit.ui_events for insert to authenticated with check (actor_user_id=auth.uid() and private.has_org_access(organization_id));
create policy re_properties_select on real_estate.properties for select to authenticated using (private.has_company_access(organization_id,company_id) and private.has_permission(organization_id,company_id,'real_estate.properties.read'));
create policy re_units_select on real_estate.units for select to authenticated using (private.has_company_access(organization_id,company_id) and private.has_permission(organization_id,company_id,'real_estate.units.read'));
create policy conversations_select_member on communications.conversations for select to authenticated using (private.has_org_access(organization_id));
create policy messages_select_member on communications.messages for select to authenticated using (private.has_org_access(organization_id));
commit;
